-- Generated by Ryoku Settings (Super + ,). Lives in the user_edits overlay,
-- overwritten on every change, so change it in the GUI, not by hand. Loaded
-- after Ryoku's defaults and before your user.lua, which still wins.

hl.config({
  general = { gaps_in = 9, gaps_out = 12, border_size = 0, layout = "scrolling", gaps_workspaces = 4 },
  decoration = { inactive_opacity = 1.0, blur = { enabled = false, size = 2, passes = 2 } },
  input = { kb_layout = "us", kb_variant = "", kb_options = "", left_handed = true, touchpad = { natural_scroll = true, clickfinger_behavior = true } },
})

hl.curve("ryokuWobble", { type = "bezier", points = { { 0.34, 1.56 }, { 0.64, 1 } } })
hl.animation({ leaf = "windowsMove", enabled = true, speed = 5, bezier = "ryokuWobble" })
do
  local ok, wc = pcall(dofile, os.getenv("HOME") .. "/.cache/ryoku/hypr-colors.lua")
  local function rgb(h, f) if type(h) ~= "string" then h = f end return "rgb(" .. h:gsub("#", "") .. ")" end
  hl.config({ general = { ["col.active_border"] = { colors = { rgb(ok and wc and wc.active, "#e0563b"), rgb(ok and wc and wc.inactive, "#313a4d") }, angle = 45 } } })
end
hl.animation({ leaf = "borderangle", enabled = true, speed = 60.0, bezier = "linear", style = "loop" })
hl.curve("ryokuRiceEase", { type = "bezier", points = { { 0.25, 0.1 }, { 0.25, 1.0 } } })
hl.animation({ leaf = "windows", enabled = true, speed = 4.0, bezier = "ryokuRiceEase", style = "popin 90%" })
hl.animation({ leaf = "windowsMove", enabled = true, speed = 4.0, bezier = "ryokuRiceEase" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 4.0, bezier = "ryokuRiceEase", style = "slide" })
hl.animation({ leaf = "fade", enabled = true, speed = 4.0, bezier = "ryokuRiceEase" })
hl.animation({ leaf = "layers", enabled = true, speed = 4.0, bezier = "ryokuRiceEase", style = "fade" })

hl.animation({ leaf = "workspaces", enabled = true, speed = 4.0, bezier = "ryokuRiceEase", style = "fade" })

hl.window_rule({ name = "ryoku-app-1", match = { class = "kitty" }, opacity = 0.8382 })
local function ryoku_plugin_loaded(name)
  for _, p in ipairs(hl.get_loaded_plugins()) do
    if p.name == name then return true end
  end
  return false
end

do
  local ok, err = pcall(function()
    hl.plugin.load(os.getenv("HOME") .. "/.local/lib/hyprland/plugins/dynamic-cursors.so")
    if ryoku_plugin_loaded("dynamic-cursors") then
      hl.config({ plugin = { dynamic_cursors = { enabled = true, mode = "stretch", shake = { enabled = true, base = 4.0 } } } })
    end
  end)
  if not ok then
    print("Ryoku plugin dynamic-cursors: " .. tostring(err))
  end
end

do
  local ok, err = pcall(function()
    hl.plugin.load(os.getenv("HOME") .. "/.local/lib/hyprland/plugins/hyprfocus.so")
    if ryoku_plugin_loaded("hyprfocus") then
      hl.config({ plugin = { hyprfocus = { enable = true, keyboard_focus_animation = "shrink", mouse_focus_animation = "none", fade_opacity = 0.8, shrink_percentage = 0.95, slide_height = 20.0 } } })
    end
  end)
  if not ok then
    print("Ryoku plugin hyprfocus: " .. tostring(err))
  end
end

do
  local ok, err = pcall(function()
    hl.plugin.load(os.getenv("HOME") .. "/.local/lib/hyprland/plugins/keysounds.so")
    if ryoku_plugin_loaded("keysounds") then
      hl.config({ plugin = { keysounds = { enabled = true, profile = "holy-panda", volume = 0.6, release = true } } })
    end
  end)
  if not ok then
    print("Ryoku plugin keysounds: " .. tostring(err))
  end
end

do
  local ok, err = pcall(function()
    hl.plugin.load(os.getenv("HOME") .. "/.local/lib/hyprland/plugins/borders-plus-plus.so")
    if ryoku_plugin_loaded("borders-plus-plus") then
      hl.config({ plugin = { borders_plus_plus = { add_borders = 1, natural_rounding = true, col = { border_1 = "rgb(FFFFFF)" }, border_size_1 = 1 } } })
    end
  end)
  if not ok then
    print("Ryoku plugin borders-plus-plus: " .. tostring(err))
  end
end

hl.on("hyprland.start", function()
  hl.exec_cmd("ryoku-wm-hyprland plugins sync >/dev/null 2>&1")
end)

hl.config({ input = { follow_mouse = 1 } })

